@Composable
private fun HomeScreen(
    uiState: HomeUiState,
    language: AppLanguage,
    modifier: Modifier = Modifier,
) {
    val context = LocalContext.current
    val copy = remember(language) { screenCopy(language) }
    val validationRoot = remember(context) { File(context.filesDir, "validation-lab") }
    val harness = remember(validationRoot) { ValidationHarness(validationRoot) }
    val liveMediaButtonCapture = remember(context) { LiveMediaButtonCapture(context) }
    DisposableEffect(liveMediaButtonCapture) {
        liveMediaButtonCapture.activate()
        onDispose { liveMediaButtonCapture.release() }
    }
    val mediaKeyDebugState = LiveMediaKeyDebugStore.state

    var permissionRefreshKey by remember { mutableStateOf(0) }
    var selectedTrigger by remember { mutableStateOf(ValidationTriggerPreset.MEDIA_KEY) }
    var selectedDevice by remember { mutableStateOf(ValidationDevicePreset.HUAWEI) }
    var hotword by remember(language) { mutableStateOf(defaultHotword(language)) }
    var title by remember(language) { mutableStateOf(defaultCaptureTitle(language)) }
    var transcript by remember(language) { mutableStateOf("") }
    var lastReport by remember { mutableStateOf<ValidationExecutionReport?>(null) }
    var recentArtifacts by remember { mutableStateOf(harness.recentArtifacts()) }

    val permissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestMultiplePermissions(),
    ) {
        permissionRefreshKey += 1
    }
    val recordAudioGranted = permissionRefreshKey.let {
        context.hasPermission(Manifest.permission.RECORD_AUDIO)
    }
    val bluetoothConnectGranted = permissionRefreshKey.let {
        context.hasBluetoothConnectPermission()
    }
    val permissionGuide = remember(
        permissionRefreshKey,
        recordAudioGranted,
        bluetoothConnectGranted,
        language,
    ) {
        harness.permissionGuide(
            recordAudioGranted = recordAudioGranted,
            bluetoothConnectGranted = bluetoothConnectGranted,
            language = language,
        )
    }
    val hardwareProbe = remember(
        permissionRefreshKey,
        bluetoothConnectGranted,
    ) {
        HardwareProbe.load(
            context = context,
            hasBluetoothPermission = bluetoothConnectGranted,
        )
    }

    LazyColumn(
        modifier = modifier
            .fillMaxSize()
            .padding(horizontal = 20.dp),
        contentPadding = PaddingValues(vertical = 16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
    ) {
        item { HeroCard(uiState) }
        item { SnapshotSection(uiState.readinessStats) }
        item {
            SectionCard(
                title = copy.hardwareProbeTitle,
                subtitle = copy.hardwareProbeSubtitle,
            ) {
                HardwareProbeSection(
                    probe = hardwareProbe,
                    mediaKeyDebugState = mediaKeyDebugState,
                    language = language,
                    onRefresh = { permissionRefreshKey += 1 },
                )
            }
        }
        item {
            SectionCard(
                title = copy.validationLabTitle,
                subtitle = copy.validationLabSubtitle,
            ) {
                ValidationLabSection(
                    language = language,
                    selectedTrigger = selectedTrigger,
                    onTriggerSelected = { selectedTrigger = it },
                    selectedDevice = selectedDevice,
                    onDeviceSelected = { selectedDevice = it },
                    hotword = hotword,
                    onHotwordChanged = { hotword = it },
                    title = title,
                    onTitleChanged = { title = it },
                    transcript = transcript,
                    onTranscriptChanged = { transcript = it },
                    lastReport = lastReport,
                    recentArtifacts = recentArtifacts,
                    permissionGuide = permissionGuide,
                    onRequestPermissions = {
                        permissionLauncher.launch(buildPermissionRequestList())
                    },
                    onRunSimulation = {
                        lastReport = harness.execute(
                            draft = ValidationCaptureDraft(
                                triggerPreset = selectedTrigger,
                                devicePreset = if (selectedTrigger.requiresDevicePreset) selectedDevice else null,
                                hotword = hotword,
                                title = title,
                                transcript = transcript,
                                tags = listOf("validation", selectedTrigger.name.lowercase()),
                            ),
                            language = language,
                        )
                        recentArtifacts = harness.recentArtifacts()
                    },
                    onLoadPlaceholderTranscript = {
                        transcript = harness.buildPlaceholderTranscript(
                            triggerPreset = selectedTrigger,
                            devicePreset = if (selectedTrigger.requiresDevicePreset) selectedDevice else null,
                            language = language,
                        )
                    },
                    onRefreshArtifacts = {
                        recentArtifacts = harness.recentArtifacts()
                    },
                )
            }
        }
        item {
            SectionCard(
                title = copy.brandSupportTitle,
                subtitle = copy.brandSupportSubtitle,
            ) {
                BrandList(brands = uiState.supportedBrands)
            }
        }
        item {
            SectionCard(
                title = copy.triggerControlTitle,
                subtitle = copy.triggerControlSubtitle,
            ) {
                TriggerLaneList(items = uiState.triggerChannels)
            }
        }
        item {
            SectionCard(
                title = copy.memoryArchiveTitle,
                subtitle = uiState.memoryHeadline,
            ) {
                StatusPill(text = uiState.memoryPathHint)
                Spacer(modifier = Modifier.height(12.dp))
                MarkdownPreviewCard(markdown = uiState.memoryPreview)
            }
        }
        item {
            SectionCard(
                title = copy.guardrailsTitle,
                subtitle = copy.guardrailsSubtitle,
            ) {
                BulletList(items = uiState.guardrails)
            }
        }
        item {
            SectionCard(
                title = copy.nextActionsTitle,
                subtitle = copy.nextActionsSubtitle,
            ) {
                NextActionList(items = uiState.nextActions)
            }
        }
        item {
            SectionCard(
                title = copy.debugChecklistTitle,
                subtitle = copy.debugChecklistSubtitle,
            ) {
                BulletList(items = uiState.debugChecklist)
            }
        }
    }
}


@Composable
private fun HardwareProbeSection(
    probe: HardwareProbeResult,
    mediaKeyDebugState: LiveMediaKeyDebugState,
    language: AppLanguage,
    onRefresh: () -> Unit,
) {
    val copy = remember(language) { screenCopy(language) }

    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        StatusPill(text = localizedHardwareStatus(probe, language))
        OutlinedButton(onClick = onRefresh) {
            Text(text = copy.refreshDevicesButton)
        }
        LiveMediaKeyStatusCard(
            state = mediaKeyDebugState,
            language = language,
        )

        if (probe.devices.isEmpty()) {
            Text(
                text = localizedHardwareEmptyMessage(probe, language),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        } else {
            probe.devices.forEach { device ->
                Card(
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.surface,
                    ),
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Text(
                                text = device.displayName,
                                style = MaterialTheme.typography.titleSmall,
                                fontWeight = FontWeight.SemiBold,
                            )
