@Composable
private fun ValidationLabSection(
    language: AppLanguage,
    selectedTrigger: ValidationTriggerPreset,
    onTriggerSelected: (ValidationTriggerPreset) -> Unit,
    selectedDevice: ValidationDevicePreset,
    onDeviceSelected: (ValidationDevicePreset) -> Unit,
    hotword: String,
    onHotwordChanged: (String) -> Unit,
    title: String,
    onTitleChanged: (String) -> Unit,
    transcript: String,
    onTranscriptChanged: (String) -> Unit,
    lastReport: ValidationExecutionReport?,
    recentArtifacts: List<ValidationArtifactPreview>,
    permissionGuide: ValidationPermissionGuide,
    onRequestPermissions: () -> Unit,
    onRunSimulation: () -> Unit,
    onLoadPlaceholderTranscript: () -> Unit,
    onRefreshArtifacts: () -> Unit,
) {
    val copy = remember(language) { screenCopy(language) }

    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        StatusPill(text = permissionGuide.statusHeadline)
        BulletList(items = permissionGuide.nextSteps)
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            Button(onClick = onRequestPermissions) {
                Text(text = copy.requestPermissionsButton)
            }
            OutlinedButton(onClick = onRefreshArtifacts) {
                Text(text = copy.refreshArchiveButton)
            }
        }
        Text(
            text = copy.triggerPresetLabel,
            style = MaterialTheme.typography.labelLarge,
            fontWeight = FontWeight.SemiBold,
        )
        PresetChipColumn(
            options = ValidationTriggerPreset.entries,
            selected = selectedTrigger,
            label = { it.localizedDisplayName(language) },
            onSelected = onTriggerSelected,
        )
        Text(
            text = selectedTrigger.localizedPathSummary(language),
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        if (selectedTrigger.requiresDevicePreset) {
            Text(
                text = copy.earphonePresetLabel,
                style = MaterialTheme.typography.labelLarge,
                fontWeight = FontWeight.SemiBold,
            )
            PresetChipColumn(
                options = ValidationDevicePreset.entries,
                selected = selectedDevice,
                label = { it.localizedDisplayName(language) },
                onSelected = onDeviceSelected,
            )
        }
        OutlinedTextField(
            value = title,
            onValueChange = onTitleChanged,
            modifier = Modifier.fillMaxWidth(),
            label = { Text(copy.captureTitleLabel) },
            supportingText = { Text(copy.captureTitleHelp) },
            singleLine = true,
        )
        if (selectedTrigger.requiresHotword) {
            OutlinedTextField(
                value = hotword,
                onValueChange = onHotwordChanged,
                modifier = Modifier.fillMaxWidth(),
                label = { Text(copy.customHotwordLabel) },
                supportingText = { Text(copy.customHotwordHelp) },
                singleLine = true,
            )
        }
        OutlinedTextField(
            value = transcript,
            onValueChange = onTranscriptChanged,
            modifier = Modifier.fillMaxWidth(),
            label = { Text(copy.transcriptSeedLabel) },
            supportingText = { Text(copy.transcriptSeedHelp) },
            minLines = 5,
        )
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            Button(onClick = onRunSimulation) {
                Text(text = copy.runSimulationButton)
            }
            OutlinedButton(onClick = onLoadPlaceholderTranscript) {
                Text(text = copy.loadPlaceholderButton)
            }
        }
        lastReport?.let { report ->
            ValidationReportCard(report = report, language = language)
        }
        ArtifactList(artifacts = recentArtifacts, language = language)
    }
}

@Composable
private fun <T> PresetChipColumn(
    options: List<T>,
    selected: T,
    label: (T) -> String,
    onSelected: (T) -> Unit,
) {
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        options.forEach { option ->
            AssistChip(
                onClick = { onSelected(option) },
                label = { Text(text = label(option)) },
                colors = AssistChipDefaults.assistChipColors(
                    containerColor = if (option == selected) {
                        MaterialTheme.colorScheme.secondaryContainer
                    } else {
                        MaterialTheme.colorScheme.surface
                    },
                    labelColor = if (option == selected) {
                        MaterialTheme.colorScheme.onSecondaryContainer
                    } else {
                        MaterialTheme.colorScheme.onSurface
                    },
                ),
            )
        }
    }
}

@Composable
private fun ValidationReportCard(
    report: ValidationExecutionReport,
    language: AppLanguage,
) {
    val copy = remember(language) { screenCopy(language) }
    Card(
        colors = CardDefaults.cardColors(
            containerColor = if (report.accepted) {
                MaterialTheme.colorScheme.secondaryContainer
            } else {
                MaterialTheme.colorScheme.errorContainer
            },
        ),
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            Text(
                text = if (report.accepted) copy.simulationSavedTitle else copy.simulationBlockedTitle,
                style = MaterialTheme.typography.titleSmall,
                fontWeight = FontWeight.SemiBold,
            )
            Text(
                text = localizedDiagnostic(report.rejectionReason ?: report.notes, language),
                style = MaterialTheme.typography.bodySmall,
            )
            report.resolvedBrand?.let {
                Text(
                    text = copy.resolvedBrandPrefix + localizedBrandLabel(it, language),
                    style = MaterialTheme.typography.bodySmall,
                )
            }
            report.markdownPath?.let {
                Text(
                    text = it,
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.primary,
                )
            }
            report.markdownBody?.let {
                MarkdownPreviewCard(markdown = it)
            }
        }
    }
}

@Composable
private fun ArtifactList(
    artifacts: List<ValidationArtifactPreview>,
    language: AppLanguage,
) {
    val copy = remember(language) { screenCopy(language) }
    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Text(
            text = copy.recentArtifactsTitle,
            style = MaterialTheme.typography.labelLarge,
            fontWeight = FontWeight.SemiBold,
        )
        if (artifacts.isEmpty()) {
            Text(
                text = copy.noArtifactsText,
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            return
        }

        artifacts.forEach { artifact ->
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surface,
                ),
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Text(
                        text = artifact.path,
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.primary,
                    )
                    MarkdownPreviewCard(markdown = artifact.preview)
                }
            }
        }
    }
}
@Composable
private fun HeroCard(uiState: HomeUiState) {
    Card(
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.primaryContainer,
        ),
    ) {
        Column(
            modifier = Modifier.padding(20.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            StatusPill(text = uiState.releaseStatus)
            Text(
                text = uiState.heroSubtitle,
                style = MaterialTheme.typography.bodyLarge,
                color = MaterialTheme.colorScheme.onPrimaryContainer,
            )
            LinearProgressIndicator(
                progress = { uiState.readinessScore },
                modifier = Modifier.fillMaxWidth(),
            )
            Text(
                text = uiState.releaseSummary,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onPrimaryContainer,
            )
        }
    }
}

@Composable
private fun SnapshotSection(stats: List<ConsoleStatUiModel>) {
    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            stats.take(2).forEach { stat ->
                SnapshotCard(
                    stat = stat,
                    modifier = Modifier.weight(1f),
                )
            }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            stats.drop(2).take(2).forEach { stat ->
                SnapshotCard(
                    stat = stat,
                    modifier = Modifier.weight(1f),
                )
            }
        }
    }
}

@Composable
private fun SnapshotCard(
    stat: ConsoleStatUiModel,
    modifier: Modifier = Modifier,
) {
    Card(
        modifier = modifier,
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surface,
        ),
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            Text(
                text = stat.label,
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Text(
                text = stat.value,
                style = MaterialTheme.typography.headlineSmall,
                fontWeight = FontWeight.Bold,
            )
            Text(
                text = stat.supportingText,
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

@Composable
private fun SectionCard(
    title: String,
    subtitle: String,
    content: @Composable () -> Unit,
) {
    Card(
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surfaceContainerLow,
        ),
    ) {
        Column(
            modifier = Modifier.padding(20.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.SemiBold,
                )
                Text(
                    text = subtitle,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
            content()
        }
    }
}

@Composable
private fun BrandList(brands: List<BrandSupportUiModel>) {
    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        brands.forEach { brand ->
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surface,
                ),
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            text = brand.name,
                            style = MaterialTheme.typography.titleSmall,
                            fontWeight = FontWeight.SemiBold,
                        )
                        StatusPill(text = brand.supportState)
                    }
                    Text(
                        text = brand.notes,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        brand.triggerModes.forEach { mode ->
                            AssistChip(
                                onClick = { },
                                label = { Text(text = mode) },
                                colors = AssistChipDefaults.assistChipColors(),
                            )
                        }
                    }
                }
            }
        }
    }
}

